<?php
require __DIR__ . '/includes/admin_bootstrap.php';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0; $row=['client_name'=>'','client_role'=>'','image'=>'','content'=>'','rating'=>5,'sort_order'=>0,'is_active'=>1]; if($id){$s=$pdo->prepare('SELECT * FROM testimonials WHERE id=?');$s->execute([$id]);$row=$s->fetch()?:$row;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$data=[trim((string)$_POST['client_name']),trim((string)$_POST['client_role']),trim((string)$_POST['image']),trim((string)$_POST['content']),max(1,min(5,(int)$_POST['rating'])),max(0,(int)$_POST['sort_order']),isset($_POST['is_active'])?1:0];if($id){$s=$pdo->prepare('UPDATE testimonials SET client_name=?,client_role=?,image=?,content=?,rating=?,sort_order=?,is_active=? WHERE id=?');$s->execute([...$data,$id]);flash('success','Testimonial updated.');}else{$s=$pdo->prepare('INSERT INTO testimonials (client_name,client_role,image,content,rating,sort_order,is_active) VALUES (?,?,?,?,?,?,?)');$s->execute($data);flash('success','Testimonial created.');}admin_redirect('testimonials.php');}
$page_title=$id?'Edit Testimonial':'Add Testimonial';require __DIR__.'/includes/header.php';
?><section class="form-panel"><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$id ?>"><div class="form-grid"><label>Client name<input name="client_name" value="<?= e($row['client_name']) ?>" required></label><label>Client role<input name="client_role" value="<?= e($row['client_role']) ?>"></label><label>Image filename<input name="image" value="<?= e($row['image']) ?>"></label><label>Rating<select name="rating"><?php for($i=1;$i<=5;$i++): ?><option value="<?= $i ?>" <?= (int)$row['rating']===$i?'selected':'' ?>><?= $i ?> stars</option><?php endfor; ?></select></label><label class="full">Testimonial<textarea name="content" rows="7" required><?= e($row['content']) ?></textarea></label><label>Sort order<input type="number" name="sort_order" value="<?= (int)$row['sort_order'] ?>"></label><label class="checkbox"><input type="checkbox" name="is_active" <?= $row['is_active']?'checked':'' ?>> Visible on website</label></div><div class="form-actions"><a class="btn secondary" href="testimonials.php">Cancel</a><button class="btn">Save testimonial</button></div></form></section><?php require __DIR__.'/includes/footer.php'; ?>
